   Choosetheincorrectpart.

1  A Performance-based pay is meant to incentivize CEOs to make a business as
   productive as possible, maximizing value for shareholders. B However, not everyone
   thinks that talent at the top is what drives profitability. C The Economic Policy
   Institute is critical of these theory. D It argues that luck is a stronger determinant of
   business success than the CEO’s acumen.

2   A Since the start of the industrial revolution, there have been threats that new
    machines – from mechanized looms to microchips – would usurp human jobs. B For
    the most part, the humans have prevailed. C Now, say some experts, with AI
    ubiquity on the horizon, the threat’s being realized: D the robots really is coming for
   some jobs.

3   A Some school cafeterias have started to use a traffic light system to guide how often
    schools should provide children with certain types of food. B The standards state
    that ‘red’ foods like cupcakes or pizza should only offered twice a term, while
    C ‘amber’ options like fruit juice should be limited. D It is recommended that ‘green’
    foods such as fruit, vegetables and yoghurt make up the majority of options.

4  Have you ever seen an ad online and thought, A “Wow, this deal is to good to be
    true”? B The offer for that jacket, those amazing shoes or tickets to an upcoming
    concert could very well be a scam. C Scams are everywhere. D And in this digital age,
      it is hard to avoid them. So how do we protect ourselves?

5   A Deep in the jungles of Borneo in Sarawak, Malaysia’s largest state, are small
    pockets of peppercorn farm. B The bright green pepper vines that nestle on steep
     hills are vibrant against the deep green of the jungle. C Cultivated mostly by
    Indigenous communities such as the Iban, D these small, family-run farms grow
   some of the best peppers in the world.





