INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','english','III','6',26,'Prova de Inglês B, seção III, item 6. Consulte o enunciado original.','6   A I came to teaching at the mature age of 36, after having worked 18 years in other
    industries. B It is the only job that me have ever loved. C I love entering the
    classroom and being present in the moment with my students, pivoting my lesson
    plan to capture their attention. D I love the moments when I see them sparkle as
    they learn something, and the way that I see a concept anew through their eyes.

7   A Digital nomads are many different types of workers. B Some are freelancers or
    independent contractors; some are entrepreneurs building their own businesses;
   and others work in full-time remote positions for companies located around the
    world. C Some are salaried, while others rely on ad hoc income. D Larger, say experts,
   many of these workers are white-collar and well-educated.

8   A Much  like the fashion  industry, food consumption  follows  trends. B But
    agricultural economics expert Dr. Wendy Umberger is worried that farmers chasing
    those trends are feeding into an oversupply of some products and a shorten of others.
    C She said growers reacting to a forever changing market with short-lived trends
   was proving unsustainable to food security as a whole. D “Farmers are constantly
    on this treadmill of having to think about what others are doing and innovate,” Dr.
   Umberger said.

9   A Music can make us feel happy and sad. B It can compel us to move in time with it
    or sing along to a melody. C It taps into some integral sense of musicality that binds
    us together. D But do the same thing happen in the minds of animals? Can a monkey
     feel moved by Mozart? Will a bird bop to a beat?

10  A It’s a common misconception that being both a student and an athlete is hard, if
    not impossible. B However, participating in sports can actually have a positive
    impact on school. C Sports force you to organize your time so that you can both go
    to practice or finish your homework. The key is finding a balance. D If you can learn
    to organize your time then you can succeed at both.





                                         E-5',ARRAY['/mext-assets/2025-b/english-p06.jpg']::text[],'choice','["A", "B", "C", "D"]'::jsonb,ARRAY['B']::text[],2,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_en(b).pdf',6,'published');
