INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','english','IV','1',31,'Prova de Inglês B, seção IV, item 1. Consulte o enunciado original.','Ⅳ Choosethemostsuitablewordorstringofwordsfromthelisttofilleachofthe
  numberedblanksinthepassagebelow.

  Human beings use language every day to think and communicate with (    1       ).
(    2      ) small children use language. Children naturally acquire the language(s)
(    3      ) in the community around them: it could be Japanese, Uyghur, Telugu, Swazi,
Basque, or, (    4       ) the hearing impaired, Japanese Sign Language (JSL), for
instance.
   While language (    5      ) sounds (or signs as in JSL), words, and sentences, it is
not simply a random sequence of sounds, words, or signs. For example, a native speaker
of Japanese instinctively knows that a sequence of sounds /straik/ (as in the English
word “strike”) is not a possible word in Japanese.
   Language is a more systematic, rule-governed mechanism. Sounds pattern in certain
regular ways in forming words, and words combine to form sentences in a consistent
manner (    6       ).
  Now you may wonder (    7      ) small children acquire their first language. Some
people have thought that children learn it by imitating what their parents and other
people around them say. That is, children were (    8      ) to learn their first language
gradually, by listening to what their parents and others say to them and by imitating it.
However, this assumption has been questioned for various reasons. For instance,
children have the ability to create sentences that they have never heard before. If they
learned their first language simply by imitating their parents and others, how could
they create sentences that are completely (    9      ) to them? The fact that children
are (    10      ) of constantly creating new sentences immediately casts serious doubt
on the assumption that children learn their first language by imitation.


 1   A  other    B  one another     C  ourselves      D  the other
 2   A  Even    B  For          C  However      D  Only
 3   A  speakers  B  speaking      C  spoke        D  spoken
 4   A  by way of B  in the case of    C  in the event of   D  regardless of
 5   A  consists of               B  exists on
     C   is composed by           D  makes up
 6   A  as well   B  namely       C  on occasion     D  so much
 7   A how     B  what         C  when        D  which
 8   A  known   B  looking forward  C  thought       D  willing

                                         E-6',ARRAY['/mext-assets/2025-b/english-p07.jpg']::text[],'choice','["A", "B", "C", "D"]'::jsonb,ARRAY['B']::text[],2,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_en(b).pdf',7,'published');
