   A  the behaviorist tradition occurred in the first half of the twentieth century.
   B  the dogs built a relation between the sound of the bell and food.
   C  the dogs could measure the production of their salivary glands by themselves.
   D  there was a prior association between a stimulus and a bell.

4  According to the article, an example of a non-arbitrary association shown in Garcia’s
   experiment is that _________
   A a noisy, flashing light causes a stomachache.
   B an electric shock causes a stomachache.
   C  flashing lights cause electric shocks.
   D sweetened water causes electric shocks.





                                         E-9

