INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','english','V-I','5',45,'Prova de Inglês B, seção V-I, item 5. Consulte o enunciado original.','9   A  difficult  B  habitual       C  novel        D  strange
 10   A  able     B  aware        C  capable       D  qualified



Ⅴ PartI:Readthefollowingpassageandselectthebestanswertoeachquestion
   listedbelowit.

    My partner Steve has a dog named Cassie. Cassie and her master have much in
common. One similarity is their attitude toward food. When dinnertime rolls around,
they both become obsessed by hunger pangs. Cassie’s solution is to stand by her food
dish as suppertime approaches. That’s not a bad idea. After all, that’s where food arrives
pretty much every night, and when she gets noticed, she gets fed. The problem with her
solution is that if someone is not in the kitchen to see her standing by her dish, she’s out
of luck until someone remembers it’s her mealtime.
      Cassie’s master is marginally smarter than his dog. Rather than going to the
location of the food, he goes to the source of the food. When he sees dinnertime in his
future, he hangs around his partner (me) because I am responsible for preparing dinner
in the family. Eventually, to get him off my back, I start getting dinner together. This
solution works whether or not someone is in the kitchen. It works whenever I am
available. His solution is admittedly not perfect. It doesn’t work if I am out of town or if
his dependent behavior annoys me.
     Cassie has established a firm connection in her own mind between eating and the
location of her food dish, a link that guides her behavior. But the dog’s master has done
something more sophisticated: He has figured out what causes food to be available (me),
and his strategy targets this cause. His dog targets the effect (the dish where her food
is delivered) and as a result sometimes goes hungry. Targeting causes rather than effects
is a pretty effective strategy for solving a number of problems. If you’re suffering from
the symptoms of a disease, it’s better to cure the disease (the cause) than the symptoms
(the effects). And if you don’t want an entire community to go hungry, you can make
more of a difference by creating conditions that allow people to feed themselves than by
simply giving people food.
    Maybe we’re being too hard on Cassie. Historically, the field of psychology spent
decades following the lead of the great Russian physiologist Ivan Pavlov, whose famous
experiments in the late nineteenth century were interpreted as showing that animals
could learn to associate any arbitrary stimuli, like the ringing of a bell and food. Pavlov

                                         E-7

found that dogs salivated before food entered their mouths (so do we). He thus measured
whether they expected food by measuring the production of their salivary glands
(roughly, how much the dogs drooled). He would feed his dogs regularly after he rang a
bell. Later, he found that the dogs would salivate merely at the sound of the bell, with
no food required. He claimed the dogs had developed an association between the sound
and food so that the sound elicited a response similar to that of food. The bell was
intended to be an arbitrary stimulus—it could have been anything as long as the dogs
could perceive it. The food was not so arbitrary. Pavlov chose it because it was something
that the dogs wanted. But he assumed that food had no prior association in the dogs’
memories to bells. That connection was arbitrary. The community of scientists believed
him: He won the Nobel Prize for this work in 1904, and Pavlov’s associationist theories
served as a cornerstone of the behaviorist tradition that ruled psychology through the
first half of the twentieth century.
     In the 1950s, a psychologist named John Garcia began poking holes in the claim
that any arbitrary association could be learned. In one of Garcia’s studies, rats were
presented with  trials  of different kinds  of paired stimuli. The rats either  first
experienced a noisy, flashing light or an unusual sweet taste in their water. Later they
were either given an electric shock or a stomachache (via a compound added to their
water). The rats easily learned to associate the noisy, flashing light with the electric
shock and the sweetened water with an impending stomachache. But they were unable
to learn the other associations, between the noisy, flashing light and the stomachache
or between the sweetened water and the electric shock.
    The kinds  of mechanisms that cause flashing lights are the same as the
mechanisms that cause electric shocks. Relatedly, drinking water with an additive—
even a sweet additive—is a potential cause of stomachache. Both of these pairings make
causal sense. The opposite pairings don’t. It’s hard to see how sweetened water could
cause an electric shock or how a flashing light could cause a stomachache. The rats were
able to learn the associations that made causal sense, but they failed to learn the ones
that were arbitrary. Garcia’s study suggests that rats are predisposed to learn causally
meaningful relations, not arbitrary links. Even rats engage in a kind of simple causal
reasoning, figuring out the likely causes of their distress.
    If rats are causal thinkers and don’t rely only on simple associations, the same is
presumably true of dogs. Pavlovian associations don’t occur between arbitrary pairs of
stimuli, they happen only when the association has some possibility of making causal
sense. So we apologize for defaming Cassie’s cognitive abilities. We have great respect
for dogs and their ability to think causally. We have even greater respect for human

                                         E-8

causal cognition.

1  According to the article, Cassie’s master seems cleverer than Cassie because
  A  her master can recognize what causes food to be available.
  B  her master easily gets food by standing by his food dish at dinner time.
  C  her master is able to realize his solution to get food is not perfect.
  D  her master is usually responsible for preparing dinner in the family.

2  According to the article,                   is helpful to solve the problem.
   A  to build a good connection between our habits and behaviors
   B  to ease the symptoms of a disease
   C  to focus on causes rather than effects
   D  to make more of a difference by creating conditions

3  According to the article, the physiologist Ivan Pavlov argued that _________
   A  the behaviorist tradition occurred in the first half of the twentieth century.
   B  the dogs built a relation between the sound of the bell and food.
   C  the dogs could measure the production of their salivary glands by themselves.
   D  there was a prior association between a stimulus and a bell.

4  According to the article, an example of a non-arbitrary association shown in Garcia’s
   experiment is that _________
   A a noisy, flashing light causes a stomachache.
   B an electric shock causes a stomachache.
   C  flashing lights cause electric shocks.
   D sweetened water causes electric shocks.





                                         E-9

5  According to the article, _________
   A  Garcia’s experiment suggested that rats were born with the ability to learn
       arbitrary relations.
   B  It is unquestionable that the associations found by Ivan Pavlov occur between
       arbitrary pairs of stimuli.
   C John Garcia supported and developed the revolutionary idea proposed by Ivan
       Pavlov.
   D Pavlovian associations happen only when the link has the potential of making
       causal sense.



