other mood disorders to metabolic malfunctions. This is why one of the newest ideas in
the emerging field of circadian medicine is to create drugs that actually amplify the
cadence of our internal timers. The scientists leading this charge think such “clock-
enhancing molecules” could help astronauts in the future stay on Earth-time even as

