   C Human beings evolved circadian rhythms tuned to the daily comings and goings
        of the sun.
   D  Our diminishing circadian rhythm cycles have been identified as the cause of
       aging in humans.

4  Based on the text, what does biologist Carrie Partch imply about circadian medicine?
   A  Circadian medicine will sustain the negative health impacts associated with
      modern lifestyles.
   B  People could one day be as healthy in their seventies as they are today in their
          fifties.
   C   Scientific studies propose to reveal the connections between critical body
       functions in humans.
   D  The research of biochemist Jake Chen and others may impede our circadian
       rhythms.





                                        E-12

5  In the final sentence, why does the author suggest that people should go outside
   more often?
   A  To improve our understanding of circadian rhythms and the human body while
       being out of the home.
   B  To persuade people to undertake specific activities inside their house or office.
   C  To stimulate and regulate healthy body rhythms by being active outdoors
       during daylight hours.
   D  To urge us to participate in certain activities or hobbies that typically take place
        late at night.





