INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','english','V-II','4',49,'Prova de Inglês B, seção V-II, item 4. Consulte o enunciado original.','5  According to the article, _________
   A  Garcia’s experiment suggested that rats were born with the ability to learn
       arbitrary relations.
   B  It is unquestionable that the associations found by Ivan Pavlov occur between
       arbitrary pairs of stimuli.
   C John Garcia supported and developed the revolutionary idea proposed by Ivan
       Pavlov.
   D Pavlovian associations happen only when the link has the potential of making
       causal sense.



Ⅴ PartII:Readthefollowingpassageandselectthebestanswertoeachquestionlisted
 belowit.

   Before there was electricity or the Internet or screens illuminated by thousands of
liquid crystals rotating polarized pulses of photons, humans mostly lived by the daily
comings and goings of the yellow burning ball of gas in the sky. Like every other
organism that walks, flies, swims, scurries, sways, or photosynthesizes on Earth, people
evolved circadian rhythms tuned to this solar circuit.
   Yours, like that of most other organisms, is controlled by waves of proteins encoded
in just a handful of master clock genes. Every day, as if tracing the rise and fall of the
sun, concentrations of special timekeeping protein complexes surge and ebb inside
nearly every cell in your body, in a sinusoidal curve that repeats itself every 24 hours.
These proteins predictably bind and release your DNA, flipping thousands of genes on
and off in synchronized choreography. They dictate more than just your sleep patterns.
Fluctuations in most of your critical body functions, including blood pressure, body
temperature, metabolism, and even your moods and behaviors all run on a meticulous
24-hour schedule.
   But lots of things can throw your clock out of whack—consuming calories at all hours
of the day, binge-watching videos on a blue-tinged screen at 3 a.m., even just getting
older. When this happens, lots of other things start to go wrong, from depression and
other mood disorders to metabolic malfunctions. This is why one of the newest ideas in
the emerging field of circadian medicine is to create drugs that actually amplify the
cadence of our internal timers. The scientists leading this charge think such “clock-
enhancing molecules” could help astronauts in the future stay on Earth-time even as

                                        E-10

they’re up in orbit or en route to Mars. Closer to home, these drugs could one day be
used to combat the obesity epidemic, stave off incurable diseases like Alzheimer’s, and
even slow aging itself.
  Up until the mid-2000s, circadian rhythm science had been mostly viewed as a kind
of cute, niche little corner of biology. But advances in gene sequencing technologies led
scientists to realize that the clock controlled more than 10,000 genes in nearly every cell
in the human body. Even more recently, they discovered that clock was malleable.
“Almost all the important functions in your body have a temporal component that we
can tweak through the power of circadian manipulation,” says biochemist Jake Chen.
He’s spent the last ten years hunting for compounds with circadian-boosting properties
and testing the hypothesis that they can make people live happier, healthier, longer
lives. If he’s right, curing or preventing some of society’s most common and costly
diseases might come down to chemically resetting our clocks. “The time has come for
the biomedical research community to recognize that biological timing is a bona fide
therapeutic target.”
   That work is just getting going. But it has other researchers in the field excited about
the long-term prospects of circadian medicine. “Having drugs that reinforce and reset
our clocks would be useful for combating the negative health effects of shift work, jet
lag, and getting off the Earth,” says biologist Carrie Partch. On the International Space
Station, astronauts have a 90-minute day, an unnatural environment that NASA’s
recent Twin Study showed can alter both circadian rhythms and your DNA.
   Back on Earth, scientists still don’t know whether the clock weakens because we get
older, or if aging is itself a symptom of a diminishing circadian rhythm. And if it’s the
latter, then invigorating our clocks could theoretically put more sand in the hourglass.
“If a molecule can make that clock stronger so that our bodies can fight off all those
changes, then 70 really would be the new 50,” Partch says. “That’s the promise of
enhancing circadian rhythms.” Modern technology may have liberated the human
species from millennia of obligate diurnality, but our bodies evolved to respond to the
sun, not to screens.
   So, until science delivers some magic clock-boosting pill, maybe just, you know, go
outside more often.





                                         E-11

