 B 技術の発展とともに時間のがい念も変化してきた。
 C 社員たちは会社のひどいやり方に憤がいして、ストライキを起こした。
 D 理由のない遅刻は会社の規則違反にがい当する。',ARRAY['/mext-assets/2025-b/japanese-iii-q08.jpg']::text[],'choice','["A", "B", "C", "D"]'::jsonb,ARRAY['B']::text[],2,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_ja(b).pdf',9,'published');
INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','japanese','III','9',43,'Prova de Japonês B, seção III, item 9. Consulte o enunciado original.','9 警察は事件の証こを見つけることができなかった。
 A 彼が発明したものはすべて特きょを取っている。
 B 田中さんは会社の難しい要求にきょ絶の態度を示した。
 C 泊まっているホテルから街までかなりのきょ離がある。
 D 賛成してもらうためには、明確な根きょが必要だ。',ARRAY['/mext-assets/2025-b/japanese-iii-q09.jpg']::text[],'choice','["A", "B", "C", "D"]'::jsonb,ARRAY['D']::text[],2,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_ja(b).pdf',9,'published');
INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','japanese','III','10',44,'Prova de Japonês B, seção III, item 10. Consulte o enunciado original.','10 祖母は何歳になっても、新しいことにいどみ続けている。
 A あの公園の中央にはちょう像が設置されている。
 B 高校生のときに大学の授業をちょう講したが、ほとんど理解できなかった。
 C 世界記録にちょう戦したが、あえなく失敗してしまった。
 D この旗は国の独立と自由の象ちょうとなっている。',ARRAY['/mext-assets/2025-b/japanese-iii-q10.jpg']::text[],'choice','["A", "B", "C", "D"]'::jsonb,ARRAY['C']::text[],2,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_ja(b).pdf',9,'published');
INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','japanese','IV','1',45,'Prova de Japonês B, seção IV, item 1. Consulte o enunciado original.','つぎ  ぶんしょう  よ             と    こた          こた           なか    もっと  てきとう
  次の文章を読んで、あとの問いに答えなさい。答えはA～Dの中から最も適当なⅣ
          ひと  えら
  ものを一つ選びなさい。



      ちい    こ        はこ  なか            だ            はこ          い
（１）小さい子どもが、箱の中からボールを出したり、また箱にボールを入れたりする
                     ちい    こ                    おな        なんかい          だいす
   ことがあります。小さい子どもは、このように、同じことを何回もすることが大好
                        おとな   い                       じぶん
  きです。これは、まわりの大人に言われてしているのではなく、自分でこのよう
                 かえ       こ      はこ  なか            だ       い           あいだ
   なことをくり返します。子どもは箱の中からボールを出したり入れたりする間に、
     おと             き           すこ  まえ    ちが      かた  はこ  なか             だ
  音がすることに気づいたり、少し前とは違うやり方で箱の中からボールを出した
        い             あたら                      たの
  り入れたりして、新しいことがわかることを楽しんでいます。



と      ぶん  ないよう  あ
問い１ 文の内容に合っているものはどれですか。
      おとな  ちい    こ      なんかい  おな
   A 大人は小さい子どもに何回も同じことをさせます。
       ちい    こ            まえ  おな      かた          だ       い
   B 小さい子どもはいつも前と同じやり方でボールを出したり入れたりします。
       ちい    こ      なんかい  おな              あたら          き
   C 小さい子どもは何回も同じことをして、新しいことに気づくことがあります。
        ちい    こ      おな        なんかい            す
   D 小さい子どもは同じことを何回もすることが好きではありません。





     にほん  おお    しょうがっこう  なつやす       にち            なつやす       にち      しょうがっこう
（２）日本の多くの小学校は夏休みが42日ありますが、夏休みが30日だけの小学校
                 ふゆ  ゆき           ふ             ゆき  がっこう   い       たいへん
  もあります。冬に雪がたくさん降るところは、雪で学校に行くのが大変です。そ
          ふゆやす    なが       なつやす    みじか             なつやす    みじか  しょうがっこう   ふゆやす
   れで、冬休みを長くして、夏休みを短くするのです。夏休みが短い小学校も、冬休
         なが        なつやす    ふゆやす                やす    なが    おな              しょう
  みが長いので、夏休みと冬休みをあわせると、休みの長さは同じになります。小
     がっこう  なが  やす        しゅくだい            なが  やす    お      しゅくだい  いそ        こ
  学校の長い休みには、宿題もあります。長い休みの終わりに宿題を急いでする子
                     なつやす    なが  がっこう  みじか  がっこう  おな
  どもがいるのは、夏休みが長い学校も短い学校も同じです。



と      ぶん  ないよう  あ
問い２ 文の内容に合っているものはどれですか。
       なつやす       にち  がっこう    なつやす       にち  がっこう    ふゆやす    なが    おな
   A 夏休みが42日の学校と、夏休みが30日の学校は、冬休みの長さは同じです。
       なつやす       にち  がっこう  こ          やす    お      いそ    しゅくだい
   B 夏休みが42日の学校の子どもだけ、休みの終わりに急いで宿題をします。
      にほん    なつやす    なが       にち  がっこう  おお
   C 日本では夏休みの長さが30日の学校が多いです。
        ふゆ  ゆき          ふ          しょうがっこう                   なつやす    みじか
   D 冬に雪がたくさん降るところの小学校は、ほかのところより夏休みが短いです。





                                       8  / 9

こめ  つく                   た         い         にほん      さいきん    た
（３）お米を作っているところを「田んぼ」と言いますが、日本では、最近、「田んぼ
               つく            にほん        しろ    こめ   た             こめ
  アート」が作られています。日本ではよく白いお米を食べますが、お米ができる
       いね        くさ  は    みどり              しろ  は  あか  は                いろ
  「稲」という草の葉は、緑だけではなく、白い葉や赤い葉など、いろいろな色が
                         いろ   は   いね          なら     う       おお     え   つく
  あります。いろいろな色の葉の稲をきれいに並べて植えて、大きい絵を作るので
          た             つく      たいへん         た             つく     え   おお
  す。田んぼアートを作るのは大変ですが、田んぼアートで作った絵は大きくてき
                                       み   く  ひと
   れいですから、いろいろなところから見に来る人もいるそうです。



と      ぶん  ないよう  あ
問い３ 文の内容に合っているものはどれですか。
         こめ        いね      くさ  つか       た            つく
   A お米ができる稲という草を使って、田んぼアートを作ります。
        た                              つく
   B 田んぼアートはだれでもかんたんに作ることができます。
        た            つく    ひと       た             え   み
   C 田んぼアートを作った人だけが田んぼアートの絵を見ることができます。
      にほん    こめ            いろ              いね  は  いろ  しろ
   D 日本のお米はいろいろな色がありますが、稲の葉の色は白だけです。



                        た  もの  はこ      あか  はこ  きいろ  はこ  つか            おお
（４）スーパーなどにある食べ物の箱には、赤い箱や黄色い箱が使われることが多いで
         あか  きいろ  あか    かん              ひと          いろ  み
   す。赤や黄色は明るい感じがしますし、人はこれらの色を見て、「おいしそうだ」、
        た                き も                  はんたい    ひと  あお  み           た
   「食べたい」、という気持ちになるからです。反対に、人は青を見てもあまり食べ
               き も                       あお  いろ  た  もの  すく           むかし  あお
   たいという気持ちになりません。それは、青い色の食べ物が少ないからで、昔は青
       はこ   た   もの   い     う                                       さいきん
  い箱に食べ物を入れて売ることはほとんどありませんでした。でも最近は、いろ
          りゆう  あお  はこ  はい    う           た  もの
   いろな理由で青い箱に入って売られている食べ物もあります。



と      ぶん  ないよう  あ
問い４ 文の内容に合っていないものはどれですか。
       あお  いろ  た  もの                    た  もの  はこ  あお  つか
   A 青い色の食べ物はぜんぜんないので、食べ物の箱に青は使われません。
       さいきん    あお  はこ  い         う       た  もの
   B 最近は、青い箱に入れられて売られる食べ物もあります。
        た  もの  う            あか  きいろ  はこ  つか
   C 食べ物を売るとき、よく赤や黄色の箱を使います。
        ひと  あか  きいろ  はこ   み           はこ  はい         た  もの  た
   D 人は赤や黄色の箱を見ると、その箱に入っている食べ物を食べたくなります。





                                       9  / 9',ARRAY['/mext-assets/2025-b/japanese-p10.jpg','/mext-assets/2025-b/japanese-p11.jpg']::text[],'choice','["A", "B", "C", "D"]'::jsonb,ARRAY['C']::text[],3,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_ja(b).pdf',10,'published');
