  1. Answer the following questions.

    (1) A small ball is thrown vertically upward from the ground with speed v0.
       The acceleration of gravity is denoted by g. Find the speed of the ball
       when it passes a point at a height h from the ground.


                                                       0 + 2gh            (c)    2gh           (a)    v20 −2gh           (b)    v2        !             !             !

                                                       0 + gh              (f)   v0           (d)    v20 −gh             (e)    v2        !             !





                                  1

(2) As shown in Fig. 1-1, one end of a string of length l is ﬁxed at point O
    and a small ball of mass m is attached to the other end. The small ball is
    moving in a uniform circular motion in the horizontal plane. The angle
    between the string and the vertical direction is θ, and the acceleration
     of gravity is denoted by g. Find the magnitude of the tension F of the
     string pulling the small ball and the period T of the circular motion.


           mg                  l                                                           l cos θ
      (a) F =      T = π              (b) F = mg cos θ,  T = π                cos θ,    " g                   "  g


                                                      l sin θ         mg                   l cos θ
       (c)  F = mg cos θ,  T = 2π          (d) F =      T = 2π                  "  g              cos θ,     "  g


           mg                   l sin θ           mg                   l
       (e)  F =      T = 2π               (f)  F =      T = 2π                  sin θ,     "  g                   sin θ,     " g





                       O


                    T

                                                                  l





                                     Fig. 1-1





                              2

(3) As shown in Fig. 1-2, in a uniform magnetic ﬁeld with a ﬂux density of
     3.0 T, a conducting wire with a length of 0.10 m is placed at 60◦to the
    magnetic ﬁeld and a current of 2.0 A is applied. Find the magnitude of
     the magnetic force on the wire.


      (a)     0.22  N         (b)     0.32  N          (c)     0.42  N


      (d)     0.52  N          (e)     0.62  N           (f)     0.72  N




                      60˅     3.0 T


                                      2.0 A





                                     Fig. 1-2



(4) An inﬁnitely long straight conducting wire has a uniformly distributed
     charge of ρ per unit length. Find the magnitude of the electric ﬁeld at
    a distance r from the wire. The proportionality constant of Coulomb’s
    law is denoted by k. Note that k and the dielectric constant of vacuum
                         1
     ε0 are related by k =         .
                        4πε0

                               kρ                    kρ
      (a)  kρr                  (b)                          (c)
                                      r                          r2

                                2kρ                   2kρ
      (d)  2kρr                  (e)                           (f)
                                      r                          r2





                              3

(5) As shown in Fig. 1-3, there is a point light source P at a depth h in a
     liquid of refractive index n. The refractive index of air is 1. We want
     to ﬂoat an opaque disk with the center at point O directly above the
     point light source on the liquid so that no light leaks into the air. Find
     the minimum radius r of the disk.

         h                                h
      (a)                                 (b)                                                                (c) √ n2        n             √ n2                 −1h                         −1

                                h
      (d)  nh                    (e)                                                                    (f) √ n2 + 1h                    √ n2 + 1



                                r
               O




                    h



                    P





                                     Fig. 1-3





