INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','physics','2','(1)',6,'Prova de Física B, seção 2, item (1). Consulte o enunciado original.','2. An object with mass m is launched from point O at an angle θ (0 < θ < π/2)
   with respect to the ground and a velocity v(> 0) at time t = 0 as shown
   in Fig. 2. The x-axis and y-axis are taken in the horizontal and vertical
   directions, respectively. The acceleration of gravity is denoted by g. Answer
   the following questions.

   (1) The object reaches its highest point at time t = t0. Find time t0.

              v cos θ                 v                      v sin θ
         (a)                      (b)                        (c)
                 g                    g                        g

              v sin 2θ                v cos 2θ                 v
         (d)                        (e)                         (f)
                 g                      g                   2g


   (2) When the object reaches its highest point, its x coordinate is a. Find
        the correct formula for a.
                v2sin2θ                  v2cos2θ                  v2sin3θ
         (a)                      (b)                        (c)
                 g                      g                      g

               v2cos3θ                  v2                       v2 sin θ cos θ
         (d)                        (e)                         (f)
                 g                    g                          g


   (3) Find the y coordinate of the highest point.
                v2sin2θ                  v2cos2θ                  v2 sin θ
         (a)                      (b)                        (c)
                2g                     2g                    2g

               v2 cos θ                  v2 sin θ                  v2 cos θ
         (d)                        (e)                         (f)
                2g                     g                      g


   (4) The object hits the ground at x = b. Find the correct formula for b.

               2v2 sin θ                2v2 cos θ                 v2 sin θ
         (a)                      (b)                        (c)
                 g                      g                     g

               v2 cos θ                 2v2 sin θ cos θ            2v2
         (d)                        (e)                         (f)
                 g                         g                  g


   (5) When θ = θ0, b takes the maximum. Find the angle θ0.
            π                  π                  π
         (a)                      (b)                        (c)
              2                     3                     4

            π                  π                  π
         (d)                        (e)                         (f)
              5                     6                     8



