INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','physics','3','(1)',11,'Prova de Física B, seção 3, item (1). Consulte o enunciado original.','3. As shown in Fig. 3, a uniform magnetic ﬁeld of magnetic ﬂux density B is
   applied vertically from front to back to a suﬃciently wide region ABCD. A
   charged particle of mass m and charge q enters region ABCD from point F
   perpendicular to AB with a speed v. The charged particle moves as shown
   in the ﬁgure and exits the region from point G perpendicular to AB. Answer
   the following questions.

   (1) Find the correct one for the charge q and the speed v′ at point G.

         (a)  q > 0,    v′ > v    (b)  q > 0,    v′ = v    (c)  q > 0,    v′ < v

         (d)  q < 0,    v′ > v    (e)  q < 0,    v′ = v    (f)  q < 0,    v′ < v


   (2) Find the magnitude of the Lorentz force on the particle.


         (a)                        (b)                          (c)          −qBv                −qvB                −qvB

            qB                      qv
         (d)                          (e)                           (f)    qvB
                v              B

   (3) Find the direct distance L between points F and G.

         m               2m               mv
         (a)                        (b)                          (c)
             qvB                 qvB                qB

            2mv               mv              2mB
         (d)                          (e)                           (f)
             qB                  2qB                      qv


   (4) Find the time for the particle to move from point F to point G.

           mπ                2mπ              mπ
         (a)                        (b)                          (c)
             2qB                 qB                 qB

         m               2m            m
         (d)                          (e)                           (f)
            qBπ                qBπ                qB





                                 7

(5) In a similar manner, a particle with three times of mass m and twice
     of the charge q enters region ABCD from point F perpendicular to AB
     with a speed v, and exits the region from point G′ which is diﬀerent
    from point G. Find the direct distance between point F and point G′
     using L obtained in the above question (3).

             1                                              3
      (a)    2L                (b)   L                   (c)    2L

             1                      2                      4
      (d)   3L                 (e)    3L                  (f)    3L





           v

    A    F    G      B





                  B



    D                    C





                                      Fig. 3





                              8',ARRAY['/mext-assets/2025-b/physics-p08.jpg','/mext-assets/2025-b/physics-p09.jpg']::text[],'choice','["a", "b", "c", "d", "e", "f"]'::jsonb,ARRAY['b']::text[],4,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_phy.pdf',8,'published');
