   charged particle of mass m and charge q enters region ABCD from point F
   perpendicular to AB with a speed v. The charged particle moves as shown
   in the ﬁgure and exits the region from point G perpendicular to AB. Answer
   the following questions.

   (1) Find the correct one for the charge q and the speed v′ at point G.

         (a)  q > 0,    v′ > v    (b)  q > 0,    v′ = v    (c)  q > 0,    v′ < v

         (d)  q < 0,    v′ > v    (e)  q < 0,    v′ = v    (f)  q < 0,    v′ < v


   (2) Find the magnitude of the Lorentz force on the particle.


         (a)                        (b)                          (c)          −qBv                −qvB                −qvB

            qB                      qv
         (d)                          (e)                           (f)    qvB
                v              B

   (3) Find the direct distance L between points F and G.

         m               2m               mv
         (a)                        (b)                          (c)
             qvB                 qvB                qB

            2mv               mv              2mB
         (d)                          (e)                           (f)
             qB                  2qB                      qv


   (4) Find the time for the particle to move from point F to point G.

           mπ                2mπ              mπ
         (a)                        (b)                          (c)
             2qB                 qB                 qB

         m               2m            m
         (d)                          (e)                           (f)
            qBπ                qBπ                qB





                                 7

(5) In a similar manner, a particle with three times of mass m and twice
     of the charge q enters region ABCD from point F perpendicular to AB
     with a speed v, and exits the region from point G′ which is diﬀerent
    from point G. Find the direct distance between point F and point G′
     using L obtained in the above question (3).

             1                                              3
      (a)    2L                (b)   L                   (c)    2L

             1                      2                      4
      (d)   3L                 (e)    3L                  (f)    3L





           v

    A    F    G      B





                  B



    D                    C





                                      Fig. 3





                              8',ARRAY['/mext-assets/2025-b/physics-p08.jpg','/mext-assets/2025-b/physics-p09.jpg']::text[],'choice','["a", "b", "c", "d", "e", "f"]'::jsonb,ARRAY['c']::text[],4,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_phy.pdf',8,'published');
INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','physics','4','(1)',16,'Prova de Física B, seção 4, item (1). Consulte o enunciado original.','4. A monatomic ideal gas with n moles is conﬁned within a cubic container of
  volume V = L3, as shown in Fig. 4. As shown in the ﬁgure, the x-, y-, and
   z-axes are taken along the sides of the cubic container. The gas comprises
  N molecules, each with a mass of m. The system is in thermal equilibrium
   at temperature T. The universal gas constant is represented as R, and the
  Boltzmann constant as k. Answer the following questions.

   (1) The pressure exerted by the gas on the container walls is a result of the
        molecules colliding with the walls. Consider a molecule in motion with a
        positive x-component velocity of vx. Assuming an elastic collision, ﬁnd
        the change in momentum when this molecule strikes the wall parallel
        to the y-z plane.

         (a)  mvx               (b)  mvx/2             (c)   vx/2


         (d)   vx                  (e)   2vx                  (f)   2mvx


   (2) A molecule is in motion with a velocity vx, where vx is positive, as in
        the previous question. Find the time interval between collisions of this
       molecule with one of the two walls parallel to the y-z plane.
            4L                 2L               L
         (a)                      (b)                        (c)
                vx                       vx                      2vx

             L2               L                L
         (d)                        (e)                         (f)
               vx                       v2x                      4vx


   (3) Let the velocity of one molecule be (vx, vy, vz). Denoting the average
        value of v2x by v2x and the average value of v2 = v2x + v2y + v2z by v2, ﬁnd
        the pressure of the gas.

        m            m            mN
         (a)      v2              (b)       v2              (c)        v2x
            V                   3V                   2V

         3mN           mN           mN
         (d)         v2x            (e)        v2              (f)        v2
             V                  3V                 V


   (4) Find the internal energy of the gas.
              1                     3                     5
         (a)  2nRT             (b)  2nRT              (c)   2nRT

         (d)  nRT                (e)  3nRT               (f)   5nRT

   (5) Find the root-mean-square speed, √ v2.


                                 9

kT                  3kT                 kT
(a)                      (b)                        (c)   " 2m          " 2m          " 2m


       kT                  3kT                 5kT
(d)                        (e)                         (f)   " 2m          " m          " m


                    z

                L





           O
                                    y                        L
       x   L



                                Fig. 4





                        10',ARRAY['/mext-assets/2025-b/physics-p10.jpg','/mext-assets/2025-b/physics-p11.jpg']::text[],'choice','["a", "b", "c", "d", "e", "f"]'::jsonb,ARRAY['f']::text[],4,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_phy.pdf',10,'published');
