INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','physics','5','(1)',21,'Prova de Física B, seção 5, item (1). Consulte o enunciado original.','5. As shown in Fig. 5-1, light with the wavelength λ emitted from a light source
   at A in the atmosphere is divided into two beams by the half-mirror at H.
  The refractive index of the atmosphere is assumed to be 1. The half-mirror
    is positioned at a 45-degree angle to the incoming light ray, One beam is
   reﬂected oﬀthe half-mirror and then oﬀthe mirror at M1. Afterward, this
  beam passes through the half-mirror and reaches the detector at B. The other
  beam ﬁrst passes through the half-mirror and is then reﬂected oﬀthe mirror
   at M2. Subsequently, this beam is reﬂected by the half-mirror and reaches
   the detector at B. The distance between the half-mirror and the mirror at
  M1 is denoted by L1. The distance to the mirror at M2 from the half-mirror
    is denoted by L2 and is larger than L1. Answer the following questions.

   (1) By adjusting the horizontal position of the mirror at M2 while maintain-
        ing L2 > L1, the diﬀerence L2 −L1 changes. The intensity of the light
       observed at B is strongest when L2 −L1 = d1. Find the relationship
       between λ and d1. Here, p is an integer.

         (a)   d1 = 2p2λ         (b)   d1 = p2λ           (c)   2d1 = p2λ


         (d)   d1 = 2pλ           (e)   d1 = pλ             (f)   2d1 = pλ

   (2) By increasing L2 −L1 from d1, the intensity of the light observed at B
        diminishes. By further increasing L2−L1, the light intensity is strongest
       again at L2 −L1 = d2. Find the correct expression for λ.                                                          1
         (a)   2 (d2 −d1)        (b)   d2 −d1             (c)   2 (d2 −d1)

                                                          1
         (d)   2 (d1 −d2)         (e)   d1 −d2              (f)   2 (d1 −d2)


  We then place a rectangular glass with thickness w and refractive index n at
  G, as shown in Fig. 5-2. The glass is positioned perpendicular to the light
  beam and remains situated between the half-mirror and the mirror at M2 in
   subsequent steps.

   (3) The intensity of the light observed at B is strongest when L2 −L1 = d3.
       Find the relationship between λ and d3. Here, q is an integer.

         (a)   d3 + nw = qλ              (b)   2 (d3 + nw) = qλ

          (c)   2 (d3 + w) = nqλ          (d)   d3 + (n −1) w = qλ

          (e)   2 [d3 + (n −1) w] = qλ     (f)   2 (d3 + w) = (n −1) qλ

                                11

(4) By increasing L2 −L1 from d3, the intensity of the light observed at B
     diminishes. By further increasing L2 −L1, the intensity of the light is
     strongest again at L2 −L1 = d4. Find the correct expression for λ.
      (a)  n (d4 −d3)        (b)   2n (d4 −d3)        (c)   2 (d4 −d3)

      (d)   (n −1) (d4 −d3)   (e)   2 (n −1) (d4 −d3) (f)   4 (d4 −d3)

                  M1



       A      H
                            M2





               B

                                     Fig. 5-1

                  M1



                    G
       A      H
                            M2

                     w



               B

                                     Fig. 5-2


                              12',ARRAY['/mext-assets/2025-b/physics-p12.jpg','/mext-assets/2025-b/physics-p13.jpg']::text[],'choice','["a", "b", "c", "d", "e", "f"]'::jsonb,ARRAY['f']::text[],5,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_phy.pdf',12,'published');
INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','physics','5','(2)',22,'Prova de Física B, seção 5, item (2). Consulte o enunciado original.','5. As shown in Fig. 5-1, light with the wavelength λ emitted from a light source
   at A in the atmosphere is divided into two beams by the half-mirror at H.
  The refractive index of the atmosphere is assumed to be 1. The half-mirror
