INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','chemistry','I','(1)',1,'Prova de Química B, seção I, item (1). Consulte o enunciado original.','(2025)

                     Nationality                     No.
CHEMISTRY                     (Please print full name, underlining
                                 family name)                      Marks
                Name



I  Select one correct answer and write the corresponding option number.

   (1)  Which of the following ions 1) to 4) has the same electron configuration as Ar atom?

        1)   F-                   2)  Na+                 3)  Al3+                 4)   S2-

   (2)  Which of the underlined atoms in the following molecules 1) to 4) has no lone pairs of
       electrons?

        1)  CO2                 2)  NH3                 3)  H2O                 4)  HCl

   (3)  Which of the following substances 1) to 4) has the lowest pH when dissolved in water?

        1)  Na2CO3             2)  NH4Cl              3)  CH3COONa         4)  CaCl2

   (4)  Which of the following substances 1) to 4) has the lowest melting point?

        1) Mg                  2)  Si                   3)  Zn                  4)  Hg

   (5)  Which of the following descriptions 1) to 4) is false for tin?

        1)  Sn can exhibit two oxidation numbers, +2 and +4.
        2)  Sn is converted to SnO2 when heated in air.
         3)  Sn is dissolved in acid to generate H2.
        4)  Sn is not dissolved in a strong base.


                             C‐1',ARRAY['/mext-assets/2025-b/chemistry-p02.jpg']::text[],'choice','["1", "2", "3", "4"]'::jsonb,ARRAY['4']::text[],2,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_che.pdf',2,'published');
