INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','chemistry','I','(6)',6,'Prova de Química B, seção I, item (6). Consulte o enunciado original.','(6)  Which of the following operations 1) to 4) produces hydrogen halide?

        1) Addition of concentrated sulfuric acid to calcium fluoride and subsequent heating.
        2) Blowing chlorine into aqueous solution of sodium hydroxide.
        3) Blowing chlorine into aqueous solution of potassium bromide.
        4) Blowing ozone into aqueous solution of potassium iodide.

  (7)  Which of the following descriptions 1) to 4) is correct for complex ions?

        1) [Ag(NH3)2]+ has an angular shape.
        2) [Cu(NH3)4]2+ has a tetrahedral shape.
        3) Aqueous solution of [Zn(NH3)4]2+ is colorless.
        4) The oxidation number of Fe in [Fe(CN)6]3- is +2.



II    Fill (  a   ) to (  e   ) in the following statements with the appropriate values. Answer the values
      to two significant figures for the calculation results of (  a   ) and (  e   ). Show the chemical
     equation appropriate to (   A       ). Use the following values if necessary;       1.73 and the
     atomic weights of O and S are 16 and 32, respectively.                                                      √3 =

(1) In the discharge process of lead-acid battery, the electrochemical reaction which occurs at the anode
    is as follows:
            Pb + SO42- → PbSO4 + 2e-
  On the other hand, the following electrochemical reaction occurs at the cathode:
                         (   A       )
   Suppose 1.0 mol of electron flows in the discharge process, the anode gains a mass of (  a   ) g.

(2) Consider the unit cell of a crystal composed of one type of atom. The number of atoms included in
    the unit cell of simple, body-centered, and face-centered cubic lattice is (  b   ), (  c   ), and
     (  d   ), respectively. Potassium crystallizes in the body-centered cubic structure under ambient
   temperature and pressure. The edge length of the unit cell of potassium is 0.523 nm. Suppose the
    nearest-neighboring potassium atoms are in contact with each other in the crystal structure, the
   atomic radius of potassium is (  e   ) nm.

                             C‐2',ARRAY['/mext-assets/2025-b/chemistry-p03.jpg']::text[],'choice','["1", "2", "3", "4"]'::jsonb,ARRAY['1']::text[],2,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_che.pdf',3,'published');
