INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','chemistry','IV','(1)-A',20,'Prova de Química B, seção IV, item (1)-A. Consulte o enunciado original.','IV Answer the following questions regarding neutralization and the electrolytic dissociation of
     electrolytes in water.

 (1) There are hydrochloric acid (solution A) and sodium hydroxide aqueous solution (solution B) of
   unknown concentration. When 10 mL of 0.1 mol/L oxalic acid (COOH)2 solution was neutralized
    and titrated with solution B, 10 mL of solution B was needed. Also, 20 mL of solution B was
    needed to neutralize 10 mL of solution A. Find the concentrations (mol/L) of the solutions A and
   B to one significant figure.

 (2) When acetic acid is dissolved in water, it electrolytically dissociates partially as in the following
    chemical equation, resulting in an equilibrium state of electrolytic dissociation.

              CH3COOH      CH3COO- + H+                  ⇆
      (2-1) In an aqueous acetic acid solution of concentration C (mol/L), let α be the degree of
         electrolytic dissociation of acetic  acid. Find the concentration (mol/L) of acetic acid
      (CH3COOH), and its ions (CH3COO- and H+) using the concentration of aqueous acetic acid
         solution C and the degree of electrolytic dissociation α in an equilibrium state of electrolytic
         dissociation, respectively.

      (2-2) Find an expression of the dissociation constant K of acetic acid using C and α.
        Also, find an approximate expression of K of acetic acid when the degree of electrolytic
        dissociation α is well below 1.

      (2-3) When the dissociation constant of  acetic acid  is 2.5×10-5 mol/L, find the proton
        concentration and pH of a 0.01 mol/L acetic acid solution to one significant figure and two
         significant figures, respectively. You may also assume that the degree of the electrolytic
         dissociation α is well below 1. Given: log102 = 0.3.





                             C‐4',ARRAY['/mext-assets/2025-b/chemistry-p05.jpg']::text[],'numeric','[]'::jsonb,ARRAY['0.4']::text[],3,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_che.pdf',5,'published');
INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','chemistry','IV','(1)-B',21,'Prova de Química B, seção IV, item (1)-B. Consulte o enunciado original.','IV Answer the following questions regarding neutralization and the electrolytic dissociation of
     electrolytes in water.

 (1) There are hydrochloric acid (solution A) and sodium hydroxide aqueous solution (solution B) of
   unknown concentration. When 10 mL of 0.1 mol/L oxalic acid (COOH)2 solution was neutralized
    and titrated with solution B, 10 mL of solution B was needed. Also, 20 mL of solution B was
    needed to neutralize 10 mL of solution A. Find the concentrations (mol/L) of the solutions A and
   B to one significant figure.

 (2) When acetic acid is dissolved in water, it electrolytically dissociates partially as in the following
