(1) For the following descriptions 1) to 5) regarding alkanes and alkenes, select one correct
    combination among options ⓐ to ⓕ.

    1) An alkane with one carbon atom is gaseous at normal temperature and normal pressure.
    2) An alkene with two carbon atoms does not have cis-trans isomers.
    3) An alkane with four carbon atoms has three structural isomers.
    4) Alkane has a larger proportion of hydrogen atoms in the molecule than alkene which has the
   same number of carbon atoms as the alkane.
    5) Complete combustion of 1 mol of alkane produces 2 mol more water than carbon dioxide.

  ⓐ 1), 3) ⓑ 2), 3), 5)  ⓒ 1), 2), 4) ⓓ 3), 4) ⓔ 2), 4), 5)  ⓕ 3), 5)

(2) For the following descriptions 1) to 5) regarding structure of organic compounds, select one correct
   combination among options ⓐ to ⓕ.

    1) The distance between carbon atoms increases in the order of ethane, ethylene, acetylene.
    2) The bond between the carbon atoms of ethane can rotate around the bond.
    3) The bond between the carbon atoms of ethylene cannot rotate around the bond.
    4) In ethylene, all atoms are collinear.
    5) In cyclohexane, all carbon atoms are coplanar.

  ⓐ 1), 2) ⓑ 1), 3)   ⓒ1), 5)  ⓓ2), 3)  ⓔ 2), 4)  ⓕ 3), 5)

