   combination among options ⓐ to ⓕ.

    1) The distance between carbon atoms increases in the order of ethane, ethylene, acetylene.
    2) The bond between the carbon atoms of ethane can rotate around the bond.
    3) The bond between the carbon atoms of ethylene cannot rotate around the bond.
    4) In ethylene, all atoms are collinear.
    5) In cyclohexane, all carbon atoms are coplanar.

  ⓐ 1), 2) ⓑ 1), 3)   ⓒ1), 5)  ⓓ2), 3)  ⓔ 2), 4)  ⓕ 3), 5)

(3) Acid-catalyzed hydrolysis of 1 mol of an ester with the molecular formula C10H16O4 yielded 1 mol
    of compound X and 2 mol of compound Y. Cis-trans isomers exist for X. Also, when X was heated,
   a dehydration reaction occurred, and a compound Z with a molecular formula C4H2O3 was obtained.
  Y is an alcohol which is oxidized to acetone.

    (3-1) Write the molecular formula of X.

    (3-2) Select one correct description about X among options 1) to 5) below.

    1) X is a dicarboxylic acid.
    2) X is a trans isomer.
    3) When hydrogen is added to the double bond between carbon atoms of X (1 mol), a maximum
                             C‐5

of 2 mol of hydrogen is added.
    4) X does not react with sodium (Na).
    5) X is an ester.

    (3-3) How many structural isomers of Y exist, including Y itself?

    (3-4) Z is a cyclic compound. How many atoms are there in the ring?

(4) Synthesis of compound A is planned by the following scheme. Find the minimum mass (g) of
    hydroxyaniline required to obtain 300 g of compound A to three significant figures.





(5) There is an ether solution of a mixture of aniline, salicylic acid and phenol. The components were
    separated by the operations shown in the following scheme.





    (5-1) Select the most suitable reagent for X among options 1) to 4).

    1) Hot water
    2) Sodium hydroxide aqueous solution
    3) Sodium chloride
    4) Hydrochloric acid





