undergoes gastrulation and forms three germ layers. The three germ layers are [ 3 ] that
is facing the surface of the embryo, [ 4 ] that will become the future digestive tract, and
[ 5 ] that lies between them. In vertebrates, part of [ 3 ] forms the [ 6 ], which produces
the central nervous system. A part of the digestive tract protrudes to form the [ 7 ]. [ 5 ]
produces various organs, such as the [ 8 ]. Embryonic cells differentiate into cells with
various functions. This involves gene expression. In red blood cells, [ 9 ] gene is
specifically expressed and a large amount of [ 9 ] protein is produced. In lens cells of the
eye, [ 10 ] gene is expressed. In nerve cells, [ 11 ] genes are activated to generate action
potential. Close to the DNA region that encodes the protein sequence of each gene is a
