INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','biology','I-4','(1)',29,'Prova de Biologia B, seção I-4, item (1). Consulte o enunciado original.','4. Judge the correctness of the following descriptions (1) – (5), and write down the letter
  “T” for the correct sentence and the letter “F” for the incorrect one in the designated
   spaces I-4 (1) to (5) on the answer sheet.


     (1) Human sperm contain DNA equivalent to 23 chromosomes.
     (2) Human sperm always have a Y chromosome.
     (3) The  first  large-scale  cell  migration  during embryogenesis occurs during
         gastrulation.
     (4) Even after the completion of gastrulation process, some cells that are to be inside
         the body in the future still face the surface of the embryo.
     (5) Differentiated lens cells have lost the genes for proteins that specifically work in
        red blood cells.





                                     4',ARRAY['/mext-assets/2025-b/biology-p05.jpg']::text[],'true-false','["T", "F"]'::jsonb,ARRAY['T']::text[],2,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_bio.pdf',5,'published');
