information can change due to damage to the DNA molecule caused by [2] or chemicals,
or due to errors in [1], etc. The change is called mutation. Mutation may cause genetic
disease or [3], but it is also essential for diversity and evolution of species. Mutations in
eukaryotic  cells  occur  at  various  levels,  ranging from  large-scale chromosomal
abnormalities  to  [4] mutations  that  are  single  nucleotide changes. Chromosomal
abnormalities include structural abnormalities such as inversions and translocations, as
well as [5], where the number of some chromosomes increases or decreases, and [6],
where the number of sets of chromosomes changes. Eukaryotes are basically diploids
with two sets of chromosomes, but tetraploids or 1)hexaploids also exist, which are
common in well-known crops. The proteins that make up cells are encoded in genes on
chromosomes using the genetic code that encodes one amino acid in [7] bases. That
information is transferred into mRNA by [8], and proteins are synthesized by [9]. The
genetic code in mRNA is called a codon, and in particular termination codes for [9] are
called [10] codons. There are a number of mutants in which a codon changes to a [10]
codon due to a single [4] mutation in a gene, which leads to a defective gene product and
significant changes in the phenotype.


1. Fill in the blank [ 1 ] – [ 10 ] in passage (A) using the most suitable term from the list
   given below (A-V) and write down the corresponding letters in the designated spaces
   II-1 (1) to (10) on the answer sheet.


  A. 3                    B. 4                        C. 6
  D. aneuploidy           E. cancer                     F. deletion
  G. end                H. final                                I. homoploidy
    J. infrared rays          K. karyotype                 L. lipid
  M. local               N. point                   O. polyploidy
   P. radiation            Q. replication               R. stop
   S. transcription          T. translation               U. translocation
  V. water





