such as tubers, bulbs, stolons, and 2)root tubers. During vegetative propagation, cells
multiply by somatic cell division so that the resulting new individuals are genetically
identical to the original ones. On the other hand, angiosperms have flowers as the place
for sexual reproduction. A typical flower has four types of organs: sepals, petals, stamens,
and pistils, and their arrangement is determined by homeotic genes. Meiosis occurs in
two of these organs, the stamen and the pistil, producing pollen and egg cells, respectively.
When pollen is attached to the stigma of the pistil, it extends the pollen tube to the embryo
sac where the egg cell is located, and fertilization occurs. The fertilized egg cell undergoes
repeated cell division and an embryo is formed.


3. From the list given below (A-I), choose two plants that produce root tubers written in
   underlined part 2) in passage (B) and write down the corresponding letter in the
   designated spaces II-3 (1) to (2) on the answer sheet.


   A. alfalfa              B. banana                  C. cassava
   D. date palm            E. fava bean                    F. potato
   G. strawberry          H. sweet potato                     I. taro





                                     6',ARRAY['/mext-assets/2025-b/biology-p07.jpg']::text[],'choice','["A", "B", "C", "D", "E", "F", "G", "H", "I"]'::jsonb,ARRAY['C','H']::text[],2,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_bio.pdf',7,'published');
