INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','biology','II-4','(1)',47,'Prova de Biologia B, seção II-4, item (1). Consulte o enunciado original.','4. Judge the correctness of the following descriptions (1) – (4) about fertilization in the
   flower, and write down the letter “T” for the correct sentence and the letter “F” for the
   incorrect one in the designated spaces II-4 (1) to (4) on the answer sheet.


   (1) The generative cell of pollen divides and becomes two sperm cells, one of which
        fertilizes the egg cell and the other fertilizes the central cell. This event is called
      double fertilization.
   (2) Upon fertilization, the egg cell becomes an embryo and the central cell becomes
      an endosperm.
   (3) Mature seeds of angiosperms always have endosperms.
   (4) In the case of self-pollination with pollen from the same plant, all the produced
     new plants have the same genetic traits as their parents.


(C) Genetic recombination is the formation of new gene combinations by cloning genes
and connecting them to foreign DNA molecules using restriction enzymes, DNA ligases,
etc. Genetic recombination makes it possible to impart new genetic traits into organisms.
Genetically modified plants that have been developed include those with enhanced
herbicide resistance, pest resistance, virus resistance, drought tolerance, etc., those with
increased nutritional value of food, or those with new flower colors.


5. Judge the correctness of the following descriptions (1) – (3) concerning genetic
   recombination, and write down the letter “T” for the correct sentence and the letter “F”
   for the incorrect one in the designated spaces II-5 (1) to (3) on the answer sheet.


     (1) Restriction enzymes recognize specific nucleotide sequences and cleave DNA.
     (2) DNA that can multiply cloned genes in host cells is called a transporter.
     (3) A common method for introducing genes into plants is to infect plant cells with
        Escherichia coli carrying the desired gene.





                                     7',ARRAY['/mext-assets/2025-b/biology-p08.jpg']::text[],'true-false','["T", "F"]'::jsonb,ARRAY['T']::text[],1,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_bio.pdf',8,'published');
