                                     8

3. What is the most relevant mechanism for the change in color-form frequency in the
   peppered moth population as described in the underlined part 2)? Choose the answer
  from options A–E given below and write down it in the designated space III-3 on the
   answer sheet.


  A. genetic drift   B. natural selection        C. hybridization
  D. mutation      E. competitive exclusion


4. Calculate the gene frequency (in percentage) of D allele in the adult moths as described
   in the underlined part 3). Choose the answer from options A–E given below and write
  down it in the designated space III-4 on the answer sheet.


   A. 6%     B. 18%    C. 24%   D. 48%    E. 60%


5. Calculate the gene frequency (in percentage) of D allele in the adults that survived bird
   predation as described in the underlined part 4), rounding it to an integer. Choose the
   answer from options A–E given below and write down it in the designated space III-5
  on the answer sheet.


   A. 40%    B. 50%    C. 60%   D. 70%    E. 80%





                                     9',ARRAY['/mext-assets/2025-b/biology-p09.jpg','/mext-assets/2025-b/biology-p10.jpg']::text[],'choice','["A", "B", "C", "D", "E"]'::jsonb,ARRAY['B']::text[],2,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_bio.pdf',9,'published');
INSERT INTO mext_questions (edition,track,subject,section,item_code,position,prompt,transcript,asset_paths,answer_type,choices,accepted_answers,points,source_url,source_page,status) VALUES (2025,'B','biology','III-4','1',57,'Prova de Biologia B, seção III-4, item 1. Consulte o enunciado original.','III. Read the following passages (A) and (B) and answer the subsequent questions 1–6.


(A) The wing and body of the peppered moth exhibit two color forms, light and dark,
which is genetically controlled by an autosomal locus, in which dark-color allele D is
dominant  over  light-color  allele L  that  is  recessive.  1)Light-colored moths  are
inconspicuous (cryptic) when they rest on light-colored tree trunks or branches and can
escape from bird predation, whereas dark-colored moths do so when they rest on dark-
colored backgrounds such as soot-darkened tree trunks. In natural habitats where tree
trunks or branches are covered with lightly colored lichens, light-colored moths are
common.
  2)During the industrial revolution in England, trunks and branches of trees in the
industrial area were soot-darkened, and this caused a dramatic increase in the frequency
of dark-colored moths, which was rare before the industrial revolution.
   3)In a population of the peppered moth, the initial numbers of adult moths with DD,
DL, and LL genotypes were 36, 48, and 16, respectively. 4)During the early half of adult
period, 14 of 16 LL moths were eaten by birds, while the other moths were all surviving.



1. What will be the ratio of the number of dark-colored F2 individuals to the number of
    light-colored F2 individuals (dark  :  light)  resulting from a cross between F1
    individuals from a DD female and an LL male parental moths? Choose the answer
   from options A–E given below and write down it in the designated space III-1 on the
   answer sheet.


   A. 1:1      B. 2:1     C. 3:1     D. 1:2     E. 1:3


2. What  is  the term  for  the phenomenon  that a  species resembles background
   environments or other species as in the underlined part 1)? Choose the answer from
   options A–E given below and write down it in the designated space III-2 on the answer
   sheet.


   A. commensalism     B. coevolution        C. sympatry
   D. mimicry           E. symbiosis





                                     8

3. What is the most relevant mechanism for the change in color-form frequency in the
   peppered moth population as described in the underlined part 2)? Choose the answer
  from options A–E given below and write down it in the designated space III-3 on the
   answer sheet.


  A. genetic drift   B. natural selection        C. hybridization
  D. mutation      E. competitive exclusion


4. Calculate the gene frequency (in percentage) of D allele in the adult moths as described
   in the underlined part 3). Choose the answer from options A–E given below and write
  down it in the designated space III-4 on the answer sheet.


   A. 6%     B. 18%    C. 24%   D. 48%    E. 60%


5. Calculate the gene frequency (in percentage) of D allele in the adults that survived bird
   predation as described in the underlined part 4), rounding it to an integer. Choose the
   answer from options A–E given below and write down it in the designated space III-5
  on the answer sheet.


   A. 40%    B. 50%    C. 60%   D. 70%    E. 80%





                                     9',ARRAY['/mext-assets/2025-b/biology-p09.jpg','/mext-assets/2025-b/biology-p10.jpg']::text[],'choice','["A", "B", "C", "D", "E"]'::jsonb,ARRAY['E']::text[],2,'https://www.studyinjapan.go.jp/ja/_mt/2026/10/exam/2025_ga_bio.pdf',9,'published');
