the tropics, [1] and [2], show similar NPP, but [1] have much larger standing crop than
[2] because the major components of [1] are [3], which have accumulated a huge amount
of biomass in [4] organs. In general, NPP of terrestrial biomes is greatly affected by [5]
and [6]. In forest biomes, there is a latitudinal trend of [7] NPP from [1], through [8], to
[9]. In other terrestrial biomes, NPP is small in [10] and [11] (biomes) where [5] and [6]
are extremely low, respectively. [11] is found in arctic and alpine zones.
  Although oceans cover about two-thirds of the earth’s surface, their total NPP accounts
for less than half of the total NPP of the world. In [12], NPP is limited by low availability
of [13] in the euphotic zone. NPP is relatively high in [14] where [13] are supplied from
lands. In marine biomes, the relative amount of standing crop of producers to NPP is
rather small compared to that in the terrestrial biomes. This is because the main producer
in marine ecosystems are [15].


